from pathlib import Path
import json
import base64

root = Path(__file__).resolve().parents[2]
data = json.loads((root/'docs/project-memory/source-data.json').read_text(encoding='utf-8'))
interviews = []
for p in sorted((root/'docs/rishe-yabi-data-pack/01_interviews').glob('*.txt')):
    text = p.read_text(encoding='utf-8')
    interviews.append({'id': int(p.stem.split('_')[1]), 'title': text.splitlines()[1], 'text': text, 'file':p.name})
payload = json.dumps({'books':data,'interviews':interviews},ensure_ascii=False).replace('</','<\\/')
